// API addresses and publishable keys for the three services.
//
// Publishable keys are public by design. Secret keys must never appear in
// this repository or on the site.
//
// Local development (127.0.0.1 / localhost): values come from
// shared/config.local.js, generated by `npm run config:local` and ignored
// by Git. Hosted site: values come from HOSTED below, filled in once the
// hosted projects exist (pending TA approval).

const HOSTED = {
  membership: { apiUrl: "", authUrl: "", publishableKey: "" },
  events: { apiUrl: "", publishableKey: "" },
  announcements: { apiUrl: "", publishableKey: "" },
};

const isLocal = ["127.0.0.1", "localhost"].includes(location.hostname);

let selected = HOSTED;
if (isLocal) {
  try {
    selected = (await import("./config.local.js")).default;
  } catch {
    selected = HOSTED;
  }
}

function freezeDeep(obj) {
  for (const value of Object.values(obj)) {
    if (value && typeof value === "object") freezeDeep(value);
  }
  return Object.freeze(obj);
}

export const config = freezeDeep(structuredClone(selected));

// True when a service has an address and key configured.
export function isConfigured(service) {
  const s = config[service];
  return Boolean(s && s.apiUrl && s.publishableKey);
}
